import { createIcons, LayoutDashboard, Files, UploadCloud, Megaphone, Copy, Link, HardDrive, History, Settings, ArrowUpRight, LogOut, Search, Plus, RefreshCw, Menu, X, ChevronLeft, ChevronRight, FileText, ArrowDownToLine, MoreHorizontal, Check, ShieldCheck, AlertTriangle, ArrowRight, Archive, RotateCcw, Trash2, ExternalLink, CheckCircle2, LoaderCircle, SlidersHorizontal, Command, Eye, Inbox } from 'lucide';
import { api, login, logout, signup, recover, changePassword, authCallback, uploadFile } from './client.js';
import { MAX_PDF_BYTES, httpsURL, PUBLIC_ORIGIN } from './domain.js';

const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={LayoutDashboard,Files,UploadCloud,Megaphone,Copy,Link,HardDrive,History,Settings,ArrowUpRight,LogOut,Search,Plus,RefreshCw,Menu,X,ChevronLeft,ChevronRight,FileText,ArrowDownToLine,MoreHorizontal,Check,ShieldCheck,AlertTriangle,ArrowRight,Archive,RotateCcw,Trash2,ExternalLink,CheckCircle2,LoaderCircle,SlidersHorizontal,Command,Eye,Inbox};
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
function hydrate(){createIcons({icons});}
function fmtDate(v,full=false){if(!v)return 'Not recorded'; const t=new Date(v);return Number.isFinite(t.getTime())?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',...(full?{timeStyle:'short'}:{}),timeZone:'Asia/Kolkata'}).format(t):'Unrecognized date';}
const bytes=v=>Number(v||0)>=1048576?(Number(v)/1048576).toFixed(1)+' MB':Math.round(Number(v||0)/1024)+' KB';
const status=r=>r.archived_at?'archived':r.published?'published':'draft';
const pill=r=>`<span class="pill ${status(r)}"><span></span>${status(r)}</span>`;
const link=(url,label,cls='')=>httpsURL(url)?`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'<span class="muted">Unavailable</span>';
const nav=[['dashboard','Overview','layout-dashboard'],['library','PDF Library','files'],['upload','Upload PDFs','upload-cloud'],['announcements','Announcements','megaphone'],['duplicates','Duplicate Manager','copy'],['links','Short Links','link'],['storage','Storage Manager','hard-drive'],['activity','Activity Logs','history'],['settings','Settings','settings']];
const state={page:'dashboard',role:null,prefs:{},records:[],total:0,pagination:1,pageSize:25,search:'',status:'all',sort:'newest',subject:'',class_name:'',chapter:'',source:'',category:'',from:'',to:'',selected:new Map(),queue:[],busy:false,groups:[],generation:0,lastRefresh:null};
let poll,searchTimer,listController,uploadRunning=false,modalDirty=false,authMode='login';
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toasts').append(node);setTimeout(()=>node.remove(),error?10000:5000);}
function setBusy(value){state.busy=value;document.querySelectorAll('[data-mutation]').forEach(b=>b.disabled=value);}
function applyPreferences(){document.documentElement.dataset.theme=state.prefs.theme||'dark';document.documentElement.dataset.motion=state.prefs.reducedMotion?'reduced':'system';}
function showError(error){if(error?.name==='AbortError')return;if(error.status===401){clearInterval(poll);authScreen('Your session expired. Sign in again to continue.');}else toast(error.message||String(error),true);}
function authScreen(message=''){
  state.role=null;clearInterval(poll);
  const setup=authMode==='signup',reset=authMode==='recover',update=authMode==='password';
  $('#app').innerHTML=`<main class="auth-layout"><section class="auth-story"><a href="/" class="brand"><span class="brand-mark">8a</span><span>8aPDF<span class="brand-sub">COMMAND CENTER</span></span></a><div class="story-main"><span class="eyebrow">A little order. A lot of possibility.</span><h1>Everything school.<br><em>Beautifully managed.</em></h1><p>Your library, announcements, and shared links.<br>One considered space to keep it all in sync.</p><div class="story-line"></div><div class="story-detail">${icon('files')}<span>One live library.<small>Every update reaches your students.</small></span></div><div class="story-detail">${icon('shield-check')}<span>Protected by design.<small>Verified access. Every action accounted for.</small></span></div></div><footer>8aPDF ADMINISTRATION<span>PRIVATE ACCESS</span></footer></section><section class="auth-form-wrap"><div class="auth-form"><div class="auth-lock">${icon('shield-check')}</div><span class="eyebrow">AUTHORIZED PERSONNEL</span><h2>${update?'Choose a new password':setup?'Set up your account':reset?'Reset your password':'Welcome back.'}</h2><p class="muted">${update?'Use a unique password with at least 12 characters.':setup?'Use the email approved by the site owner. Verify your email before signing in.':reset?'Receive a secure link to reset your password.':'Sign in to your administration workspace.'}</p><form id="auth-form">${update?'':`<label>Email address<input type="email" name="email" placeholder="you@school.edu" autocomplete="email" required></label>`}${reset?'':`<label>Password<input type="password" name="password" minlength="${setup||update?12:1}" autocomplete="${setup||update?'new-password':'current-password'}" placeholder="${setup?'Create a strong password':'Your password'}" required></label>`}<p class="form-error" role="alert">${esc(message)}</p><button class="btn primary full" type="submit">${update?'Update password':setup?'Create account':reset?'Send reset link':'Sign in securely'} ${icon('arrow-right')}</button></form><div class="auth-links">${!update?`<button class="text-btn" data-auth="${setup||reset?'login':'recover'}">${setup||reset?'Back to sign in':'Forgot password?'}</button>${!setup&&!reset?'<button class="text-btn" data-auth="signup">First-time setup</button>':''}`:''}</div><div class="security-note">${icon('shield-check')}Supabase authentication · Restricted administrator access</div><a href="/" class="back-link">${icon('chevron-left')} Back to the student website</a></div></section></main>`;
  hydrate();document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;authScreen();});
  $('#auth-form').onsubmit=async e=>{
    e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;const form=new FormData(e.target);
    try{
      if(update){await changePassword(form.get('password'));toast('Password updated.');authMode='login';await start();}
      else if(setup){await signup(form.get('email'),form.get('password'));authMode='login';authScreen('Check your email to confirm the account, then sign in here.');}
      else if(reset){await recover(form.get('email'));authMode='login';authScreen('If this account exists, a password reset link has been sent.');}
      else{await login(form.get('email'),form.get('password'));await start();}
    }catch(err){e.target.querySelector('.form-error').textContent=err.message;button.disabled=false;}
  };
}
function shell(){
  $('#app').innerHTML=`<button class="mobile-scrim" id="nav-scrim" aria-label="Close navigation"></button><aside class="sidebar"><a class="brand" href="/admin"><span class="brand-mark">8a</span><span>8aPDF<span class="brand-sub">COMMAND CENTER</span></span></a><div class="workspace-switch"><span class="workspace-avatar">8a</span><div>School workspace<small>Administration</small></div><span class="tiny-dot"></span></div><span class="nav-label">WORKSPACE</span><nav aria-label="Administration">${nav.map(([key,title,i],n)=>`${n===6?'<div class="nav-divider"></div><span class="nav-label">OPERATIONS</span>':''}<a href="#${key}" data-nav="${key}">${icon(i)}<span>${title}</span>${key==='upload'?'<span class="nav-plus">+</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="/" target="_blank" rel="noopener" class="website-link">${icon('arrow-up-right')}Open website</a><div class="account"><span class="avatar">${state.role==='super_admin'?'SA':'AD'}</span><div>Administrator<small>${state.role==='super_admin'?'Super Admin':'Admin'}</small></div><button class="icon-btn" id="logout" aria-label="Log out">${icon('log-out')}</button></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" id="nav-toggle" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span class="slash">/</span><b id="breadcrumb">Overview</b></div><div class="topbar-right"><span class="connection"><span></span>Supabase connected</span><span class="top-divider"></span><button class="icon-btn" id="refresh" aria-label="Refresh data">${icon('refresh-cw')}</button><span class="avatar small">${state.role==='super_admin'?'SA':'AD'}</span></div></header><main id="content" tabindex="-1"></main><footer class="main-footer"><span>8aPDF Command Center <span class="footer-dot">·</span> Secure administration</span><span id="last-refresh"></span></footer></div>`;
  $('#logout').onclick=async()=>{if(uploadRunning){toast('Wait for the upload to finish or cancel it first.',true);return;}try{await logout();}catch(e){toast('Signed out locally. Server session revocation could not be confirmed.',true);}finally{authMode='login';authScreen();}};
  $('#refresh').onclick=()=>loadPage(true).catch(showError);
  $('#nav-toggle').onclick=()=>document.body.classList.toggle('nav-open');$('#nav-scrim').onclick=()=>document.body.classList.remove('nav-open');
  hydrate();
}
function pageHead(kicker,title,description,actions='') {return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
const button=(text,action,i='plus',cls='primary')=>`<button class="btn ${cls}" data-action="${action}">${icon(i)}${text}</button>`;
function skeleton(){return '<div class="skeleton-heading skeleton"></div><div class="stats-grid">'+Array.from({length:4},()=>'<div class="skeleton-card skeleton"></div>').join('')+'</div><div class="skeleton-table skeleton"></div>';}
function empty(title,description,i='inbox'){return `<div class="empty-state">${icon(i)}<h3>${title}</h3><p>${description}</p></div>`;}
function actionsBind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action).catch(showError));}
async function handleAction(action){
  if(action==='new-pdf'){location.hash='upload';return;}
  if(action==='new-announcement')return editRecord(null,'announcements');
  if(action==='new-link')return linkForm();
  if(action==='scan'){return loadDuplicates();}
  if(action==='export')return exportSelected();
  if(action==='filters'){$('#advanced-filters').hidden=!$('#advanced-filters').hidden;return;}
  if(action.startsWith('bulk:'))return bulk(action.slice(5),state.page==='duplicates'?'study_materials':currentTable());
  if(action==='select-recommended'){
    state.selected.clear();for(const g of state.groups.filter(g=>g.confidence==='confirmed'))for(const r of g.records.slice(1))state.selected.set(r.id,r);
    updateDuplicateToolbar();toast(`${state.selected.size} later records selected for review.`);return;
  }
}
async function loadPage(refresh=false){
  const generation=++state.generation;listController?.abort();listController=new AbortController();
  const label=nav.find(n=>n[0]===state.page)?.[1]||'Overview';$('#breadcrumb').textContent=label;
  document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===state.page));
  document.body.classList.remove('nav-open');
  if(!refresh)$('#content').innerHTML=skeleton();
  try{
    if(state.page==='dashboard'){
      const [data,dupes]=await Promise.all([api('overview',{},listController.signal),api('duplicates',{strictness:'exact'},listController.signal)]);
      if(generation!==state.generation)return;renderDashboard(data,dupes.groups.length);
    }else if(['library','announcements','links','storage','activity'].includes(state.page)){
      const table=currentTable();const data=await api('list',{table,page:state.pagination,pageSize:state.pageSize,search:state.search,status:state.status,sort:state.sort,subject:state.subject,source:state.source,class_name:state.class_name,chapter:state.chapter,category:state.category,from:state.from,to:state.to},listController.signal);
      if(generation!==state.generation)return;state.records=data.records;state.total=data.total;renderList();
    }else if(state.page==='upload')renderUpload();
    else if(state.page==='duplicates')await loadDuplicates(generation);
    else if(state.page==='settings')renderSettings();
    state.lastRefresh=new Date();const el=$('#last-refresh');if(el)el.textContent='Updated '+new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(state.lastRefresh)+' IST';
  }catch(e){if(e.name==='AbortError')return; if(!refresh){$('#content').innerHTML=empty('Unable to load this section',esc(e.message),'alert-triangle')+button('Retry','scan','refresh-cw','secondary');const retry=$('[data-action="scan"]');if(retry)retry.onclick=()=>loadPage().catch(showError);hydrate();}throw e;}
}
function renderDashboard(d,dupes){
  const metric=(label,value,i,meta)=>`<article class="stat-card"><div class="stat-label">${label}${icon(i)}</div><div class="stat-number" data-count="${value}">${value.toLocaleString('en-IN')}</div><p>${meta}</p></article>`;
  $('#content').innerHTML=pageHead('YOUR WORKSPACE, AT A GLANCE','A clearer view.','Everything you need to keep the school day moving.',`<a class="btn secondary" href="/" target="_blank" rel="noopener">${icon('arrow-up-right')}Open website</a>${button('Upload PDFs','new-pdf','plus')}`)+`<div class="overview-banner"><div><span class="pill published"><span></span>Live school library</span><h2>Good things, kept in order.</h2><p>Every published update is available to your students.<br>Your workspace is connected to the existing 8aPDF database.</p><a href="#library" class="banner-link">Explore your library ${icon('arrow-right')}</a></div><div class="banner-art" aria-hidden="true"><div class="art-page back"></div><div class="art-page front">${icon('file-text')}<div></div><div></div><div></div><span>8aPDF</span></div><span class="art-check">${icon('check')}</span></div></div><div class="stats-grid">${metric('Total PDFs',d.pdfs,'files',`<span class="positive">+${d.pdfsToday}</span> uploaded today`)}${metric('Announcements',d.announcements,'megaphone',`<span class="positive">+${d.announcementsToday}</span> added today`)}${metric('Duplicate groups',dupes,'copy','Confirmed matches · review manually')}${metric('Custom short links',d.links,'link','Permanent, shareable destinations')}</div><div class="dashboard-columns"><section class="panel recent-panel"><div class="panel-head"><div><h2>Recent PDFs</h2><p>The latest additions to your library</p></div><a class="text-link" href="#library">View all ${icon('arrow-up-right')}</a></div>${d.recent.length?d.recent.map(r=>`<div class="recent-row"><span class="document-icon">${icon('file-text')}</span><div class="recent-title"><a href="#library" data-open-record="${esc(r.id)}">${esc(r.title)}</a><span>${esc(r.subject||'Uncategorized')} <b>·</b> ${fmtDate(r.source_date||r.date_iso)}</span></div>${pill(r)}<button class="icon-btn" data-open-url="${esc(r.pdf_url)}" aria-label="Open PDF">${icon('arrow-up-right')}</button></div>`).join(''):empty('A fresh start','Upload a PDF to start your library.')}<div class="panel-foot"><span>${d.latestUpload?'Latest verified upload: '+fmtDate(d.latestUpload,true):'Insertion time for historical imports is inferred.'}</span></div></section><div class="dashboard-right"><section class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>A shorter path to getting things done</p></div></div><div class="quick-grid">${[['new-pdf','upload-cloud','Upload PDFs'],['new-announcement','megaphone','Add announcement']].map(([a,i,t])=>`<button class="quick-action" data-action="${a}">${icon(i)}<span>${t}</span></button>`).join('')}<a class="quick-action" href="#duplicates">${icon('copy')}<span>Review duplicates</span></a><a class="quick-action" href="#links">${icon('link')}<span>Manage links</span></a></div></section><section class="panel storage-card"><div class="storage-icon">${icon('hard-drive')}</div><div><h3>PDF storage</h3><strong>${bytes(d.storageBytes)}</strong><p>Tracked admin uploads · study-pdfs</p></div><a class="icon-btn" href="#storage" aria-label="Manage storage">${icon('arrow-up-right')}</a></section></div></div><div class="dashboard-columns lower"><section class="panel"><div class="panel-head"><div><h2>School announcements</h2><p>Latest school message date first</p></div><a href="#announcements" class="text-link">View all ${icon('arrow-up-right')}</a></div>${d.notices.map(r=>`<div class="notice-row"><span class="notice-date">${fmtDate(r.message_date||r.created_at)}</span><h3>${esc(r.title)}</h3><p>${esc(r.description||r.original_message||'').slice(0,220)}</p><div>${pill(r)}<span class="muted">${esc(r.category||'General')}</span></div></div>`).join('')||empty('No announcements yet','Create your first school update.')}</section><section class="panel"><div class="panel-head"><div><h2>Activity timeline</h2><p>Recorded changes, with a clear trail</p></div><a href="#activity" class="icon-btn" aria-label="All activity">${icon('arrow-up-right')}</a></div><div class="timeline">${d.activity.map(r=>`<div class="timeline-item"><span class="timeline-dot">${icon(r.action==='created'?'plus':r.action==='archived'?'archive':'check')}</span><div><strong>${esc(r.action.replaceAll('_',' '))} ${esc(r.record_type.replaceAll('_',' '))}</strong><p>${esc(r.after_data?.title||r.before_data?.title||r.record_id)}</p><small>${fmtDate(r.created_at,true)} · ${r.actor_id?'Administrator':'Automation / server'}</small></div></div>`).join('')||empty('No activity yet','Future changes will appear here.')}</div><div class="panel-foot">${d.failed.length?`${d.failed.length} recent failed upload(s). <a href="#storage">Review recovery details</a>`:'No failed tracked uploads.'} Sync error telemetry is unavailable.</div></section></div>`;
  actionsBind();animateStats();document.querySelectorAll('[data-open-url]').forEach(b=>b.onclick=()=>openURL(b.dataset.openUrl));
  document.querySelectorAll('[data-open-record]').forEach(a=>a.onclick=e=>{e.preventDefault();editRecord(d.recent.find(r=>r.id===a.dataset.openRecord),'study_materials');});hydrate();
}
function animateStats(){if(state.prefs.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(const node of document.querySelectorAll('[data-count]')){const target=Number(node.dataset.count),start=performance.now();const tick=now=>{const p=Math.min(1,(now-start)/420);node.textContent=Math.round(target*(1-(1-p)**3)).toLocaleString('en-IN');if(p<1&&node.isConnected)requestAnimationFrame(tick);};requestAnimationFrame(tick);}}
function currentTable(){return {library:'study_materials',announcements:'announcements',links:'short_links',storage:'admin_uploads',activity:'admin_audit_logs'}[state.page];}
function toolbar(){const catalog=['library','announcements'].includes(state.page);return `<div class="table-toolbar"><div class="search-box">${icon('search')}<input id="search" type="search" aria-label="Search records" placeholder="${state.page==='links'?'Search slug, PDF title or URL…':'Search your '+(state.page==='library'?'PDF library':state.page)+'…'}" value="${esc(state.search)}"><kbd>⌘ K</kbd></div><div class="toolbar-filters">${catalog?`<select id="status-filter" aria-label="Publication status">${[['all','All active'],['published','Published'],['draft','Unpublished'],['archived','Archived']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort records">${[['newest','School date: newest'],['oldest','School date: oldest'],['inserted','Latest inserted'],['edited','Recently edited']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select>${button('Filters','filters','sliders-horizontal','secondary compact')}`:''}</div></div>${catalog?`<div class="advanced-filters" id="advanced-filters" hidden>${(state.page==='library'?['subject','class_name','chapter','source']:['subject','category']).map(k=>`<label>${k.replace('_',' ')}<input data-filter="${k}" value="${esc(state[k])}" placeholder="Any ${k.replace('_',' ')}"></label>`).join('')}<label>From school date<input type="date" data-filter="from" value="${state.from}"></label><label>To school date<input type="date" data-filter="to" value="${state.to}"></label><button class="btn secondary" id="apply-filters">Apply filters</button><button class="text-btn" id="clear-filters">Clear</button></div>`:''}`;}
function selectionToolbar(){return `<div class="selection-bar" id="selection-bar" ${state.selected.size?'':'hidden'}><span><strong>${state.selected.size}</strong> selected</span><div>${['publish','unpublish','archive','restore','delete','subject',...(state.page==='announcements'?['category']:[])].filter(x=>x!=='delete'||state.role==='super_admin').map(x=>button(x[0].toUpperCase()+x.slice(1),'bulk:'+x,x==='delete'?'trash-2':x==='archive'?'archive':'check','secondary compact')).join('')}${button('Export','export','arrow-down-to-line','secondary compact')}${state.page==='library'?'<button class="btn secondary compact" id="selected-duplicates">Find duplicates</button>':''}</div><button class="icon-btn" id="clear-selection" aria-label="Clear selection">${icon('x')}</button></div>`;}
function renderList(){
  const table=currentTable(),catalog=['library','announcements'].includes(state.page),pdf=state.page==='library';
  const title={library:['CONTENT LIBRARY','Your PDF library.','A considered home for every school document.'],announcements:['SCHOOL COMMUNICATION','School announcements.','Keep students and parents in the loop.'],links:['PERMANENT CONNECTIONS','Short links. Long useful lives.','Manage shareable aliases without losing their original destinations.'],storage:['FILE OPERATIONS','Your storage, accounted for.','Verified uploads, recovery details, and safe file cleanup.'],activity:['AUDIT TRAIL','Every action has a story.','A permanent record of changes from administrators and automation.']}[state.page];
  $('#content').innerHTML=pageHead(...title,catalog?button(pdf?'Upload PDFs':'Add announcement',pdf?'new-pdf':'new-announcement'):state.page==='links'?button('Create short link','new-link','link'):'')+`<section class="panel library-panel">${toolbar()}${catalog?selectionToolbar():''}<div class="table-scroll"><table><thead><tr>${catalog?'<th class="checkbox-cell"><input type="checkbox" id="select-all" aria-label="Select this page"></th>':''}${catalog?`<th>${pdf?'DOCUMENT':'ANNOUNCEMENT'}</th><th>SUBJECT</th>${pdf?'<th>CHAPTER / CLASS</th>':'<th>CATEGORY</th>'}<th>SCHOOL DATE</th><th>STATUS</th><th>ADDED / UPDATED</th><th class="align-right">ACTIONS</th>`:state.page==='links'?'<th>SHORT LINK</th><th>LINKED PDF</th><th>CREATED</th><th class="align-right">ACTIONS</th>':state.page==='storage'?'<th>FILE</th><th>SIZE</th><th>STATE</th><th>CREATED</th><th class="align-right">ACTIONS</th>':'<th>ACTION</th><th>RECORD</th><th>ACTOR</th><th>WHEN</th><th></th>'}</tr></thead><tbody>${state.records.map(r=>catalog?catalogRow(r,pdf):state.page==='links'?shortRow(r):state.page==='storage'?storageRow(r):auditRow(r)).join('')}</tbody></table></div>${!state.records.length?empty(state.search?'No matching records':'Nothing here yet',state.status==='archived'?'Archived records will remain available to restore.':'Try adjusting your filters or add something new.'):''}<div class="pagination"><span>${state.total?((state.pagination-1)*state.pageSize+1)+'–'+Math.min(state.pagination*state.pageSize,state.total):'0'} of ${state.total.toLocaleString('en-IN')} records</span><div><label>Per page <select id="page-size">${[25,50,100].map(n=>`<option ${n===state.pageSize?'selected':''}>${n}</option>`).join('')}</select></label><button class="icon-btn" id="previous-page" aria-label="Previous page" ${state.pagination===1?'disabled':''}>${icon('chevron-left')}</button><span>Page ${state.pagination} of ${Math.max(1,Math.ceil(state.total/state.pageSize))}</span><button class="icon-btn" id="next-page" aria-label="Next page" ${state.pagination*state.pageSize>=state.total?'disabled':''}>${icon('chevron-right')}</button></div></div></section>`;
  actionsBind();hydrate();
  $('#search').oninput=e=>{state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.pagination=1;loadPage(true).then(()=>{const s=$('#search');s?.focus();s?.setSelectionRange(state.search.length,state.search.length);}).catch(showError);},350);};
  for(const [id,key] of [['status-filter','status'],['sort-filter','sort'],['page-size','pageSize']])if($('#'+id))$('#'+id).onchange=e=>{state[key]=key==='pageSize'?Number(e.target.value):e.target.value;state.pagination=1;loadPage(true).catch(showError);};
  $('#previous-page').onclick=()=>{state.pagination--;loadPage(true).catch(showError);};$('#next-page').onclick=()=>{state.pagination++;loadPage(true).catch(showError);};
  if(catalog){
    $('#apply-filters').onclick=()=>{document.querySelectorAll('[data-filter]').forEach(e=>state[e.dataset.filter]=e.value);state.pagination=1;loadPage(true).catch(showError);};
    $('#clear-filters').onclick=()=>{for(const k of ['subject','source','class_name','chapter','category','from','to'])state[k]='';state.pagination=1;loadPage(true).catch(showError);};
    $('#select-all').checked=!!state.records.length&&state.records.every(r=>state.selected.has(r.id));
    $('#select-all').onchange=e=>{for(const r of state.records)if(e.target.checked)state.selected.set(r.id,r);else state.selected.delete(r.id);renderList();};
    document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{const r=state.records.find(r=>r.id===b.dataset.select);if(b.checked)state.selected.set(r.id,r);else state.selected.delete(r.id);renderList();});
    $('#clear-selection').onclick=()=>{state.selected.clear();renderList();};
    if($('#selected-duplicates'))$('#selected-duplicates').onclick=()=>{state.duplicateIds=[...state.selected.keys()];location.hash='duplicates';};
  }
  bindRecordActions();
}
function catalogRow(r,pdf){return `<tr><td class="checkbox-cell"><input type="checkbox" data-select="${esc(r.id)}" ${state.selected.has(r.id)?'checked':''} aria-label="Select ${esc(r.title)}"></td><td><div class="document-cell"><span class="document-icon">${icon(pdf?'file-text':'megaphone')}</span><div><button class="row-title" data-row="edit" data-id="${esc(r.id)}">${esc(r.title)}</button><p>${esc(pdf?(r.source||(r.id.startsWith('edusecure-')?'EduSecure':'Imported')):(r.description||r.original_message||''))}</p>${pdf?`<span class="record-id">${esc(r.original_filename||r.id)}</span>`:''}</div></div></td><td><span class="subject-chip">${esc(r.subject||'Uncategorized')}</span></td><td>${esc(pdf?(r.chapter||'—'):(r.category||'General'))}${pdf?`<small class="cell-sub">${esc(r.class_name||'Class not specified')}</small>`:''}</td><td class="nowrap">${fmtDate(pdf?(r.source_date||r.date_iso):r.message_date)}</td><td>${pill(r)}</td><td class="nowrap">${fmtDate(r.inserted_at||r.created_at)}<small class="cell-sub">${r.inserted_at?'Verified insertion':'Imported · time inferred'}</small>${r.updated_at?`<small class="cell-sub">Edited ${fmtDate(r.updated_at)}</small>`:''}</td><td><div class="row-actions">${pdf?`<button class="icon-btn" data-row="preview" data-id="${esc(r.id)}" aria-label="Preview PDF">${icon('eye')}</button>`:''}<button class="icon-btn" data-row="menu" data-id="${esc(r.id)}" aria-label="Actions for ${esc(r.title)}">${icon('more-horizontal')}</button></div></td></tr>`;}
function shortRow(r){return `<tr><td><strong>${link(PUBLIC_ORIGIN+'/'+r.slug,'/'+esc(r.slug),'short-slug')}</strong><small class="cell-sub">${esc(r.document_id||'Historical alias')}</small></td><td><div class="link-title">${esc(r.title)}</div>${link(r.url,esc(r.url),'url-text')}</td><td class="nowrap">${fmtDate(r.created_at,true)}</td><td><div class="row-actions"><button class="icon-btn" data-row="copy-short" data-id="${esc(r.slug)}" aria-label="Copy short link">${icon('copy')}</button><button class="icon-btn" data-row="health" data-id="${esc(r.slug)}" aria-label="Check destination">${icon('shield-check')}</button><button class="icon-btn" data-row="transfer-link" data-id="${esc(r.slug)}" aria-label="Transfer link to a compatible PDF">${icon('arrow-right')}</button><button class="icon-btn danger" data-row="delete-link" data-id="${esc(r.slug)}" aria-label="Delete short link">${icon('trash-2')}</button></div></td></tr>`;}
function storageRow(r){const url='https://xudhjwojgxblbsebkzso.supabase.co/storage/v1/object/public/study-pdfs/'+r.storage_path;return `<tr><td><div class="document-cell"><span class="document-icon">${icon('file-text')}</span><div><strong>${esc(r.filename)}</strong><small class="cell-sub">${esc(r.storage_path)}</small>${r.error?`<span class="error-text">${esc(r.error)}</span>`:''}</div></div></td><td class="nowrap">${bytes(r.size_bytes)}</td><td><span class="pill ${r.state==='ready'?'published':r.state==='failed'?'archived':'draft'}">${esc(r.state)}</span></td><td>${fmtDate(r.created_at,true)}</td><td><div class="row-actions">${r.state!=='deleted'?link(url,icon('arrow-up-right'),'icon-btn'):''}${['failed','pending'].includes(r.state)?`<button class="btn secondary compact" data-row="retry-upload" data-id="${r.id}">Reselect & retry</button>`:''}${state.role==='super_admin'&&['ready','failed','deleting'].includes(r.state)?`<button class="icon-btn danger" data-row="delete-file" data-id="${r.id}" aria-label="Clean up unreferenced file">${icon('trash-2')}</button>`:''}</div></td></tr>`;}
function auditRow(r){return `<tr><td><span class="audit-action">${icon(r.action==='deleted'?'trash-2':r.action==='archived'?'archive':'check-circle-2')}${esc(r.action.replaceAll('_',' '))}</span></td><td><strong>${esc(r.after_data?.title||r.before_data?.title||r.record_id)}</strong><small class="cell-sub">${esc(r.record_type)} · ${esc(r.record_id)}</small></td><td><span>${r.actor_id?'Administrator':'Automation / server'}</span><small class="cell-sub">${esc(r.actor_id||'')}</small></td><td class="nowrap">${fmtDate(r.created_at,true)}</td><td><button class="icon-btn" data-row="audit" data-id="${r.id}" aria-label="View audit changes">${icon('eye')}</button></td></tr>`;}
function openURL(url){if(!httpsURL(url)){toast('This record has no safe HTTPS URL.',true);return;}window.open(url,'_blank','noopener,noreferrer');}
async function copy(value){await navigator.clipboard.writeText(value);toast('Link copied.');}
function bindRecordActions(){document.querySelectorAll('[data-row]').forEach(b=>b.onclick=async()=>{try{
  const r=state.records.find(r=>String(r.id||r.slug)===b.dataset.id);const action=b.dataset.row;
  if(action==='edit')return editRecord(r,currentTable());
  if(action==='preview')return preview(r.pdf_url,r.title);
  if(action==='menu')return recordMenu(r,currentTable());
  if(action==='copy-short')return copy(PUBLIC_ORIGIN+'/'+r.slug);
  if(action==='transfer-link')return transferLinkForm(r);
  if(action==='health'){const h=await api('link_health',{slug:r.slug});return modal('Destination health',`<div class="health-result">${icon(h.accessible===false?'alert-triangle':'shield-check')}<p>${esc(h.message)}</p><dl><dt>Library record matches</dt><dd>${h.verifiedRecord?'Yes':'No'}</dd><dt>Public listing</dt><dd>${h.published?'Published':'Hidden / historical'}</dd><dt>HTTP availability</dt><dd>${h.accessible===null?'External host not checked':h.accessible?'Accessible':'Inaccessible'}</dd></dl>${link(r.url,'Open destination '+icon('arrow-up-right'),'btn secondary')}</div>`);}
  if(action==='delete-link'){if(await confirmDialog('Delete /'+r.slug+'?',`This permanent shared URL will stop working. The PDF is kept.`, 'DELETE '+r.slug)){await api('link_delete',{slug:r.slug,confirm:'DELETE '+r.slug});toast('Short link deleted.');await loadPage(true);}return;}
  if(action==='delete-file'){if(await confirmDialog('Permanently remove this file?',`${r.filename}. Cleanup is allowed only when no surviving PDF, announcement or short link references it. Deleted record snapshots cannot restore a removed file.`, 'DELETE FILE')){await api('storage_delete',{uploadId:r.id,confirm:'DELETE FILE'});toast('Unreferenced storage file removed.');await loadPage(true);}return;}
  if(action==='retry-upload'){state.retryUpload=r;location.hash='upload';return;}
  if(action==='audit')return modal('Audit detail',`<p class="muted">${esc(r.action)} · ${fmtDate(r.created_at,true)}</p><div class="audit-comparison"><div><h3>Before</h3><pre>${esc(JSON.stringify(r.before_data,null,2))}</pre></div><div><h3>After</h3><pre>${esc(JSON.stringify(r.after_data,null,2))}</pre></div></div>`,'wide');
}catch(e){showError(e);}});}
function modal(title,content,cls=''){
  const d=$('#modal');if(d.open)d.close();modalDirty=false;
  d.className=cls;d.innerHTML=`<div class="modal-head"><div><span class="eyebrow">8aPDF ADMINISTRATION</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" id="modal-close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${content}</div>`;
  d.showModal();hydrate();$('#modal-close').onclick=()=>requestModalClose();d.oncancel=e=>{if(modalDirty){e.preventDefault();requestModalClose();}};d.querySelectorAll('input,textarea,select').forEach(e=>e.addEventListener('input',()=>modalDirty=true));return d;
}
function requestModalClose(){if(modalDirty&&!window.confirm('Discard unsaved changes?'))return;modalDirty=false;$('#modal').close();}
async function confirmDialog(title,description,phrase){
  const d=modal(esc(title),`<div class="confirmation-icon">${icon('alert-triangle')}</div><p>${esc(description)}</p><label>Type <strong>${esc(phrase)}</strong> to confirm<input id="confirmation-text" autocomplete="off" spellcheck="false"></label><div class="modal-actions"><button class="btn secondary" id="confirm-cancel">Cancel</button><button class="btn danger-btn" id="confirm-ok" disabled>Confirm</button></div>`);
  return new Promise(resolve=>{
    let resolved=false;
    // A close event from the previous dialog can arrive after this one opens.
    const onClose=()=>{if(!d.open)done(false);};
    const done=value=>{if(resolved)return;resolved=true;d.removeEventListener('close',onClose);modalDirty=false;if(d.open)d.close();resolve(value);};
    $('#confirmation-text').oninput=e=>$('#confirm-ok').disabled=e.target.value!==phrase;
    $('#confirm-ok').onclick=()=>done(true);$('#confirm-cancel').onclick=()=>done(false);
    d.addEventListener('close',onClose);
  });
}
function recordMenu(r,table){
  const pdf=table==='study_materials';
  modal('Document actions',`<h3 class="record-menu-title">${esc(r.title)}</h3>${pill(r)}<div class="menu-grid">${[['edit','Edit details','settings'],...(pdf?[['preview','Preview PDF','eye'],['copy','Copy original URL','copy'],['download','Download PDF','arrow-down-to-line'],['short','Create short link','link']]:[['message','Read / copy full message','file-text']]),[r.archived_at?'restore':'archive',r.archived_at?'Restore record':'Archive record',r.archived_at?'rotate-ccw':'archive'],['publish',r.published?'Unpublish':'Publish','check'],['duplicate','Create intentional duplicate','copy'],...(state.role==='super_admin'?[['delete','Permanently delete','trash-2']]:[])].map(([a,t,i])=>`<button class="menu-action" data-menu="${a}">${icon(i)}${t}${icon('chevron-right')}</button>`).join('')}</div><dl class="record-details"><dt>Record ID</dt><dd>${esc(r.id)}</dd><dt>Source</dt><dd>${esc(r.source||'Imported')}</dd><dt>Original insertion</dt><dd>${fmtDate(r.inserted_at||r.created_at,true)} ${r.inserted_at?'':'(inferred)'}</dd><dt>Last update</dt><dd>${fmtDate(r.updated_at,true)}</dd>${pdf?`<dt>Original URL</dt><dd>${link(r.pdf_url,esc(r.pdf_url),'url-text')}</dd><dt>SHA-256</dt><dd class="break-all">${esc(r.file_checksum||'Unavailable for this record')}</dd>`:`<dt>Source message ID</dt><dd>${esc(r.source_message_id||'Not recorded')}</dd>`}</dl>`);
  document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=async()=>{try{const action=b.dataset.menu;modalDirty=false;$('#modal').close();
    if(action==='edit')return editRecord(r,table);
    if(action==='preview')return preview(r.pdf_url,r.title);
    if(action==='copy')return copy(r.pdf_url);
    if(action==='download')return openURL(PUBLIC_ORIGIN+'/api/download?url='+encodeURIComponent(r.pdf_url)+'&filename='+encodeURIComponent((r.title||'study-material').replace(/[\\/:*?"<>|]/g,'-').slice(0,120)+'.pdf'));
    if(action==='short')return linkForm(r);
    if(action==='message')return fullMessage(r);
    if(action==='duplicate'){if(await confirmDialog('Create a duplicate?', 'A separate unpublished copy will be created. The source PDF file will be shared, not uploaded again.','DUPLICATE')){await api('duplicate',{table,id:r.id,confirm:'DUPLICATE'});toast('Unpublished copy created.');await loadPage(true);}return;}
    const operation=action==='publish'?(r.published?'unpublish':'publish'):action;state.selected=new Map([[r.id,r]]);await bulk(operation,table);
  }catch(e){showError(e);}});
}
function fullMessage(r){modal(esc(r.title),`<div class="full-message">${esc(r.original_message||r.raw?.originalMessage||r.description||'No message recorded.')}</div>${r.attachment_url?link(r.attachment_url,'Open attachment','btn secondary'):''}<div class="modal-actions"><button class="btn primary" id="copy-message">${icon('copy')}Copy message</button></div>`);$('#copy-message').onclick=()=>copy(r.original_message||r.description||'').catch(showError);}
function preview(url,title){if(!httpsURL(url))return toast('No valid PDF URL.',true);modal('PDF preview',`<p>${esc(title)}</p><p class="muted">Some external hosts block embedded previews. Use Open PDF if needed.</p><iframe title="PDF preview" sandbox="allow-scripts" referrerpolicy="no-referrer" class="pdf-preview" src="${esc(url)}"></iframe><div class="modal-actions">${link(url,'Open PDF '+icon('arrow-up-right'),'btn primary')}</div>`,'wide');}
function metadataForm(r={},table='study_materials'){
  const pdf=table==='study_materials',date=pdf?(r.source_date||r.date_iso):r.message_date;
  return `<div class="form-grid"><label class="span-2">${pdf?'PDF':'Announcement'} title<input name="title" required maxlength="500" value="${esc(r.title||'')}" placeholder="Give it a clear, useful title"></label><label>Subject<input name="subject" maxlength="120" value="${esc(r.subject??state.prefs.defaultSubject??'')}" placeholder="e.g. Science"></label>${pdf?`<label>Chapter<input name="chapter" maxlength="200" value="${esc(r.chapter||'')}" placeholder="Chapter name or number"></label><label>Class<input name="class_name" maxlength="80" value="${esc(r.class_name||'')}" placeholder="e.g. 8A"></label>`:`<label>Category<input name="category" maxlength="120" value="${esc(r.category||'General')}" list="announcement-categories"></label><datalist id="announcement-categories"><option>General</option><option>Homework</option><option>Exam</option><option>Event</option><option>Reminder</option><option>Circular</option></datalist>`}<label>${pdf?'School / source date':'Message date'}<input name="${pdf?'source_date':'message_date'}" type="date" value="${esc(date?String(date).slice(0,10):'')}"></label>${!pdf?`<label>Priority<select name="priority">${['low','normal','high','urgent'].map(p=>`<option ${p===(r.priority||'normal')?'selected':''}>${p}</option>`).join('')}</select></label>`:''}<label class="span-2">Short description<textarea name="description" rows="3" maxlength="10000" placeholder="A little context for your students">${esc(r.description||'')}</textarea></label>${pdf?`<label class="span-2">Tags<input name="tags" value="${esc((r.tags||[]).join(', '))}" placeholder="revision, homework, term 1"></label>`:`<label class="span-2">Full original message<textarea name="original_message" rows="7" maxlength="40000" placeholder="Write the complete announcement">${esc(r.original_message||r.raw?.originalMessage||'')}</textarea></label><label class="span-2">PDF attachment${r.attachment_url?`<small>Current: ${link(r.attachment_url,'Open attachment')}</small>`:''}<input name="attachment" type="file" accept="application/pdf,.pdf"><small>Optional · PDF only · maximum 20 MB</small></label>`}<label class="toggle-field span-2"><span><strong>Publish ${r.id?'on save':'when ready'}</strong><small>Make this available on the student website.</small></span><input name="published" type="checkbox" role="switch" ${(r.published??state.prefs.defaultPublished??false)?'checked':''} ${r.archived_at?'disabled':''}></label></div>`;
}
function readMetadata(form,table){const f=new FormData(form),out={};for(const [k,v]of f)if(k!=='attachment'&&k!=='published'&&k!=='short_slug'&&k!=='allow_duplicate')out[k]=v;out.published=f.has('published');if(table==='study_materials')out.tags=String(out.tags||'').split(',').map(t=>t.trim()).filter(Boolean);return out;}
function editRecord(r,table){
  const createId=crypto.randomUUID(),uploadId=crypto.randomUUID();
  const d=modal(r?'Edit '+(table==='study_materials'?'PDF details':'announcement'):'New announcement',`<form id="editor">${metadataForm(r||{},table)}<p class="form-error" role="alert"></p><div class="modal-actions"><button class="btn secondary" type="button" id="editor-cancel">Cancel</button><button class="btn primary" type="submit" data-mutation>${icon('check')}Save ${r?'changes':'announcement'}</button></div></form>`,'editor');
  $('#editor-cancel').onclick=requestModalClose;
  $('#editor').onsubmit=async e=>{e.preventDefault();const form=e.target;const b=form.querySelector('[type=submit]');b.disabled=true;try{
    const details=readMetadata(form,table),attachment=new FormData(form).get('attachment');
    if(attachment?.size){
      await uploadFile({id:uploadId,file:attachment,table,recordId:r?.id,version:r?.version},details,{controller:()=>{},progress:p=>b.textContent='Sending '+p+'%',stage:s=>b.textContent=stageLabel(s)});
    }else await api('save',{table,id:r?.id,createId,version:r?.version,data:details});
    modalDirty=false;d.close();toast('Announcement saved.'.replace('Announcement',table==='study_materials'?'PDF':'Announcement'));await loadPage(true);signalPublicRefresh();
  }catch(err){form.querySelector('.form-error').textContent=err.message;b.disabled=false;}};
}
async function bulk(operation,table=currentTable()){
  const items=[...state.selected.values()];if(!items.length)return toast('Select at least one record.',true);
  let value;if(['subject','category'].includes(operation)){value=window.prompt('New '+operation+' for '+items.length+' records:');if(value===null)return;}
  const phrase=operation.toUpperCase()+' '+items.length;
  if(['archive','delete'].includes(operation)){
    const list=items.slice(0,8).map(r=>r.title).join(' • ')+(items.length>8?' …':'');
    if(!await confirmDialog(`${operation==='delete'?'Permanently delete':'Archive'} ${items.length} record(s)?`,`${list}. ${operation==='delete'?'Selected records will be deleted immediately; archiving first is not required. Active short links block deletion. Files are retained; deleted metadata is kept in a server recovery snapshot.':'Records will leave public listings and remain recoverable. Existing permanent short links keep their original destination.'}`,phrase))return;
  }
  setBusy(true);const results=[];
  try{
    for(let offset=0;offset<items.length;offset+=50){const chunk=items.slice(offset,offset+50);const result=await api('bulk',{table,operation,items:chunk.map(r=>({id:r.id,version:r.version})),value,confirm:operation.toUpperCase()+' '+chunk.length});results.push(...result.results);toast(`Processed ${Math.min(offset+50,items.length)} of ${items.length}.`);}
    for(const r of results)if(r.ok)state.selected.delete(r.id);
    const failed=results.filter(r=>!r.ok);toast(`${results.length-failed.length} completed${failed.length?', '+failed.length+' need attention':''}.`,!!failed.length);
    await loadPage(true);signalPublicRefresh();
    if(failed.length)modal('Batch results',`<p>Every record was handled independently. Successful changes are saved.</p>${results.map(r=>`<div class="batch-result ${r.ok?'':'error-text'}">${icon(r.ok?'check-circle-2':'alert-triangle')}<div><strong>${esc(items.find(x=>x.id===r.id)?.title||r.id)}</strong><p>${r.ok?'Completed':esc(r.error)}</p></div></div>`).join('')}`);
  }finally{setBusy(false);}
}
async function exportSelected(){const ids=[...state.selected.keys()];if(!ids.length)return toast('Select records first.',true);const r=await api('export',{table:currentTable(),ids});const u=URL.createObjectURL(new Blob([JSON.stringify(r.records,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='8apdf-'+currentTable()+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Selected records exported.');}
function linkForm(pdf){
  modal('Create a permanent short link',`<p class="muted">Only a real, published PDF can receive a short link. Existing aliases are never overwritten.</p><form id="link-form"><label>Published PDF ${pdf?`<input value="${esc(pdf.title)}" disabled>`:`<input id="pdf-lookup" placeholder="Search the live PDF library" autocomplete="off"><select id="pdf-choice" size="5" aria-label="Choose published PDF" required></select>`}</label><label>Custom name<div class="slug-input"><span>the-8apdf.vercel.app/</span><input name="slug" pattern="[a-z0-9][a-z0-9-]{1,30}[a-z0-9]" minlength="3" maxlength="32" value="${pdf?esc(pdf.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,25).replace(/-$/,'')):''}" placeholder="science-notes" required></div></label><p class="form-error" role="alert"></p><div class="modal-actions"><button class="btn primary" type="submit">${icon('link')}Create short link</button></div></form>`);
  let options=[],timer,lookupGeneration=0;
  if(!pdf){const search=async()=>{const generation=++lookupGeneration;try{const r=await api('list',{table:'study_materials',status:'published',search:$('#pdf-lookup').value,pageSize:100});if(generation!==lookupGeneration||!$('#pdf-choice'))return;options=r.records;$('#pdf-choice').innerHTML=options.map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('');}catch(e){showError(e);}};$('#pdf-lookup').oninput=()=>{clearTimeout(timer);timer=setTimeout(search,300);};search();}
  $('#link-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const row=pdf||options.find(r=>r.id===$('#pdf-choice').value);if(!row)throw Error('Choose a published PDF.');const slug=new FormData(e.target).get('slug');await api('link_create',{slug,documentId:row.id,pdfUrl:row.pdf_url});modalDirty=false;$('#modal').close();toast('Permanent short link created.');await loadPage(true);}catch(err){e.target.querySelector('.form-error').textContent=err.message;b.disabled=false;}};
}
function signalPublicRefresh(){try{localStorage.setItem('8apdf_admin_catalogue_changed',String(Date.now()));new BroadcastChannel('8apdf-catalogue').postMessage('refresh');}catch{}}
async function transferLinkForm(r){
  const {records}=await api('link_candidates',{slug:r.slug});
  if(!records.length)return modal('No compatible keeper yet',`<p>Link /${esc(r.slug)} stays at its original destination. A transfer requires another published PDF referencing the same URL, with path case and query parameters preserved. Publish a compatible retained record first.</p>${link(r.url,'Open original destination','btn secondary')}`);
  modal('Transfer without changing the link',`<p>The shared slug and its exact destination URL stay unchanged. Only the associated library record changes.</p><form id="transfer-form"><label>Retained published PDF<select name="keeper">${records.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><p class="url-text">${esc(r.url)}</p><p class="form-error"></p><div class="modal-actions"><button class="btn primary" type="submit">Transfer association</button></div></form>`);
  $('#transfer-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('link_transfer',{slug:r.slug,documentId:new FormData(e.target).get('keeper'),confirm:'TRANSFER'});modalDirty=false;$('#modal').close();toast('Link transferred. Original URL preserved.');await loadPage(true);}catch(err){e.target.querySelector('.form-error').textContent=err.message;b.disabled=false;}};
}
const stageLabel=s=>({sending:'Sending file',validating:'Validating PDF',uploading:'Uploading to Storage',link:'Verifying public link',saving:'Saving metadata',publishing:'Confirming publication',ready:'Ready to share'}[s]||s);
function saveQueue(){try{sessionStorage.setItem('8apdf_admin_queue',JSON.stringify(state.queue.filter(j=>j.status!=='ready').map(({id,name,size,metadata,table})=>({id,name,size,metadata,table}))));}catch{}}
function renderUpload(){
  $('#content').innerHTML=pageHead('FROM YOUR DEVICE TO THE LIBRARY','Make room for something new.','Drop your PDFs, add the details, and publish when you’re ready.')+`<div class="upload-layout"><section><div class="drop-zone" id="drop-zone" role="button" tabindex="0" aria-label="Choose PDF files"><div class="upload-glyph">${icon('upload-cloud')}</div><span class="eyebrow">A DIRECT CONNECTION TO YOUR LIBRARY</span><h2>Drop your PDFs here.</h2><p>Or choose files from your computer or phone.</p><button class="btn primary" id="choose-files">${icon('plus')}Choose PDFs</button><small>PDF only <span>·</span> Up to 20 MB each <span>·</span> Multiple files welcome</small><input type="file" id="file-input" accept="application/pdf,.pdf" multiple hidden></div>${state.retryUpload?`<div class="inline-notice">${icon('rotate-ccw')}Reselect <strong>${esc(state.retryUpload.filename)}</strong> to recover upload ${esc(state.retryUpload.id)}.</div>`:''}<div class="queue-heading"><h2>Upload queue <span id="queue-count">${state.queue.length}</span></h2><span class="muted">Details are saved only when you publish or save a draft.</span></div><div id="upload-queue"></div></section><aside class="upload-guide panel"><span class="eyebrow">THOUGHTFULLY HANDLED</span><h2>A file.<br>A link.<br><em>Ready for school.</em></h2><ol>${[['A valid PDF','Type, signature and size verified on the server.'],['A permanent public link','Stored in your existing Supabase project.'],['Your details, preserved','Titles, subjects, dates and source metadata.'],['Published when you say','Students see it without a redeployment.']].map(([t,p],i)=>`<li><span>${i+1}</span><div><strong>${t}</strong><p>${p}</p></div></li>`).join('')}</ol><div class="guide-note">${icon('shield-check')}Every upload is authorized, verified, and recorded. Public file URLs remain accessible if the library entry is later unpublished.</div></aside></div>`;
  const input=$('#file-input'),zone=$('#drop-zone');$('#choose-files').onclick=e=>{e.stopPropagation();input.click();};zone.onclick=e=>{if(e.target!==input)input.click();};zone.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click();}};input.onchange=e=>{addFiles([...e.target.files]);input.value='';};
  for(const event of ['dragover','dragleave','drop'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.toggle('dragging',event==='dragover');if(event==='drop')addFiles([...e.dataTransfer.files]);});
  const allButton=document.createElement('button');allButton.className='btn secondary compact';allButton.id='upload-all';allButton.textContent='Upload all queued PDFs';$('.queue-heading').append(allButton);
  allButton.onclick=async()=>{if(uploadRunning)return toast('Wait for the current upload to finish.');allButton.disabled=true;try{for(const id of state.queue.filter(j=>j.file&&j.status==='queued').map(j=>j.id)){const form=$(`[data-job-form="${id}"]`);if(form&&form.reportValidity())await form.onsubmit(new Event('submit',{cancelable:true}));}}finally{allButton.disabled=false;}};
  renderQueue();hydrate();
}
function addFiles(files){for(const file of files){
  if(!/\.pdf$/i.test(file.name)||file.type!=='application/pdf'){toast(file.name+': choose a PDF file.',true);continue;}if(!file.size||file.size>MAX_PDF_BYTES){toast(file.name+': maximum PDF size is 20 MB.',true);continue;}
  const recovery=state.retryUpload&&state.retryUpload.filename===file.name&&Number(state.retryUpload.size_bytes)===file.size?state.retryUpload:null;
  const waiting=state.queue.find(j=>!j.file&&j.name===file.name&&j.size===file.size);
  if(waiting){waiting.file=file;waiting.status='queued';continue;}
  state.queue.push({id:recovery?.id||crypto.randomUUID(),file,name:file.name,size:file.size,status:'queued',progress:0,metadata:{title:file.name.replace(/\.pdf$/i,'').replace(/[_-]+/g,' '),subject:state.prefs.defaultSubject||'',published:state.prefs.defaultPublished||false}});if(recovery)state.retryUpload=null;
}saveQueue();renderQueue();}
function renderQueue(){const root=$('#upload-queue');if(!root)return;$('#queue-count').textContent=state.queue.length;
  root.innerHTML=state.queue.map(j=>`<article class="queue-card" data-job="${j.id}"><div class="queue-file"><span class="document-icon">${icon('file-text')}</span><div><strong>${esc(j.name)}</strong><small>${bytes(j.size)} · ${j.file?'PDF document':'Reselect this file to recover'}</small></div><button class="icon-btn" data-remove-job="${j.id}" aria-label="${j.xhr?'Cancel upload':'Remove file'}">${icon('x')}</button></div>${j.status==='ready'?`<div class="upload-success">${icon('check-circle-2')}<div><strong>${j.result.record.published?'Published. Ready to share.':'Saved as a draft.'}</strong><p>${esc(j.result.record.title)}</p><div class="success-actions">${link(j.result.record.pdf_url||j.result.record.attachment_url,'View PDF '+icon('arrow-up-right'),'btn secondary compact')}<button class="btn secondary compact" data-copy-job="${j.id}">${icon('copy')}Copy PDF link</button><a class="btn secondary compact" href="/pdfs" target="_blank" rel="noopener">View website</a></div>${j.result.shortLink?`<p>${link(PUBLIC_ORIGIN+'/'+j.result.shortLink.slug,esc(PUBLIC_ORIGIN+'/'+j.result.shortLink.slug),'url-text')}</p>`:''}${j.result.shortLinkError?`<p class="error-text">PDF saved. Short link was not created: ${esc(j.result.shortLinkError)}</p>`:''}</div></div>`:`<form data-job-form="${j.id}">${metadataForm(j.metadata)}<label>Optional short-link name<input name="short_slug" maxlength="32" placeholder="e.g. science-notes" value="${esc(j.metadata.short_slug||'')}"><small>Requires publication. Leave blank to create a link later.</small></label><label class="checkbox-label"><input type="checkbox" name="allow_duplicate" ${j.metadata.allow_duplicate?'checked':''}>Allow an intentional duplicate if identical content exists</label><div class="upload-progress ${['uploading','error'].includes(j.status)?'':'hidden'}" aria-live="polite"><div class="progress-label"><span>${esc(j.error||stageLabel(j.stage||'sending'))}</span><span>${j.status==='uploading'&&j.stage==='sending'?j.progress+'%':''}</span></div><progress max="100" ${j.stage==='sending'?`value="${j.progress}"`:j.status==='error'?'value="0"':''}></progress><ol class="upload-stages">${['validating','uploading','link','saving','publishing','ready'].map((s,i)=>`<li class="${j.stage===s?'current':''}"><span>${i+1}</span>${stageLabel(s)}</li>`).join('')}</ol></div><div class="modal-actions"><span class="muted">${j.status==='error'?'Same UUID retained for safe retry.':'Public file hosting · secure metadata save'}</span><button type="submit" class="btn primary" ${j.status==='uploading'||!j.file?'disabled':''}>${icon(j.status==='error'?'rotate-ccw':'upload-cloud')}${j.status==='error'?'Retry upload':'Upload & save'}</button></div></form>`}</article>`).join('')||empty('Your next upload starts here','Choose PDFs above, then review their details.','upload-cloud');
  document.querySelectorAll('[data-remove-job]').forEach(b=>b.onclick=()=>{const j=state.queue.find(j=>j.id===b.dataset.removeJob);if(j.xhr){j.xhr.abort();j.xhr=null;}else{state.queue=state.queue.filter(x=>x!==j);saveQueue();renderQueue();}});
  document.querySelectorAll('[data-copy-job]').forEach(b=>b.onclick=()=>{const j=state.queue.find(j=>j.id===b.dataset.copyJob);copy(j.result.record.pdf_url||j.result.record.attachment_url).catch(showError);});
  document.querySelectorAll('[data-job-form]').forEach(form=>{
    const j=state.queue.find(j=>j.id===form.dataset.jobForm);
    form.oninput=()=>{j.metadata={...readMetadata(form,'study_materials'),short_slug:form.elements.short_slug.value,allow_duplicate:form.elements.allow_duplicate.checked};saveQueue();};
    form.onsubmit=async e=>{e.preventDefault();if(uploadRunning){toast('One upload is being verified. Wait for it to finish, then save the next file.');return;}
      uploadRunning=true;j.status='uploading';j.stage='sending';j.error=null;j.metadata={...readMetadata(form,'study_materials'),short_slug:form.elements.short_slug.value,allow_duplicate:form.elements.allow_duplicate.checked};renderQueue();
      try{j.result=await uploadFile(j,j.metadata,{controller:xhr=>j.xhr=xhr,progress:p=>{j.progress=p;updateJobProgress(j);},stage:s=>{j.stage=s;updateJobProgress(j);}});j.status='ready';j.stage='ready';if(state.prefs.notifications!==false)toast('PDF and public link verified. '+(j.result.record.published?'Published on the website.':'Draft saved.'));signalPublicRefresh();}
      catch(err){j.status='error';j.error=err.message;showError(err);}finally{uploadRunning=false;j.xhr=null;saveQueue();renderQueue();}
    };
  });hydrate();
}
function updateJobProgress(j){const el=$(`[data-job="${j.id}"] .upload-progress`);if(!el)return;el.classList.remove('hidden');el.querySelector('.progress-label span').textContent=stageLabel(j.stage);el.querySelector('.progress-label span:last-child').textContent=j.stage==='sending'?j.progress+'%':'';const p=el.querySelector('progress');if(j.stage==='sending')p.value=j.progress;else p.removeAttribute('value');const stages=['validating','uploading','link','saving','publishing','ready'];el.querySelectorAll('.upload-stages li').forEach((li,i)=>{li.classList.toggle('current',stages[i]===j.stage);li.classList.toggle('done',stages.indexOf(j.stage)>i);});}
async function loadDuplicates(generation=state.generation){
  const d=await api('duplicates',{strictness:state.prefs.duplicateStrictness||'balanced',ids:state.duplicateIds,showIgnored:state.showIgnored},listController?.signal);if(generation!==state.generation)return;state.groups=d.groups;
  $('#content').innerHTML=pageHead('A LITTLE LESS REPETITION','Clarity, without the clutter.',`${d.scanned} active PDFs scanned. Every decision stays in your hands.`,button('Scan again','scan','refresh-cw','secondary'))+`<div class="duplicate-summary"><span class="pill published">${d.groups.filter(g=>g.confidence==='confirmed').length} confirmed</span><span class="pill draft">${d.groups.filter(g=>g.confidence==='probable').length} probable</span><span class="pill">${d.groups.filter(g=>g.confidence==='possible').length} possible similarities</span><label class="checkbox-label"><input type="checkbox" id="show-ignored" ${state.showIgnored?'checked':''}>Show ignored groups</label>${state.duplicateIds?'<button class="text-btn" id="scan-everything">Scan entire library</button>':''}</div><div class="inline-notice">${icon('shield-check')}Matching titles are a warning, never proof. Original priority uses insertion time; imported dates are labelled as inferred.</div><div class="duplicate-toolbar" id="duplicate-toolbar"></div><div class="duplicate-groups">${d.groups.map((g,idx)=>`<section class="panel duplicate-group"><div class="panel-head"><div><span class="eyebrow">${g.confidence==='confirmed'?'CONFIRMED DUPLICATE':g.confidence==='probable'?'PROBABLE DUPLICATE':'POSSIBLE SIMILAR DOCUMENTS'}</span><h2>Group ${String(idx+1).padStart(2,'0')}</h2><p>${esc(g.reason)}</p></div><button class="text-btn" data-ignore="${idx}">${g.ignored?'Restore warning':'Ignore warning'}</button></div><div class="comparison-grid">${g.records.map((r,n)=>`<article class="compare-card ${n===0?'keeper':''}"><div class="compare-label">${n===0?icon('shield-check')+'Recommended keeper':icon('copy')+'Later candidate'}<label><input type="checkbox" data-duplicate-select="${esc(r.id)}" ${state.selected.has(r.id)?'checked':''} aria-label="Select ${esc(r.title)}"></label></div><span class="document-icon">${icon('file-text')}</span><h3>${esc(r.title)}</h3><dl><dt>Subject</dt><dd>${esc(r.subject||'—')}</dd><dt>School date</dt><dd>${fmtDate(r.source_date||r.date_iso)}</dd><dt>Inserted</dt><dd>${fmtDate(r.inserted_at||r.created_at,true)}${!r.inserted_at?'<small class="inferred">Inferred from import · order uncertain</small>':''}</dd><dt>Short links</dt><dd>${r.links.length?r.links.map(l=>link(PUBLIC_ORIGIN+'/'+l.slug,'/'+esc(l.slug))).join(', '):'None'}</dd><dt>Original URL</dt><dd>${link(r.pdf_url,esc(r.pdf_url),'url-text')}</dd></dl>${r.links.length?'<div class="link-warning">'+icon('alert-triangle')+'Permanent short links protect this PDF from deletion.</div>':''}<div class="compare-actions"><button class="btn ${n===0?'primary':'secondary'} compact" data-keep="${idx}:${n}">${icon('check')}Keep this · archive others</button><button class="icon-btn" data-compare-open="${idx}:${n}" aria-label="Preview PDF">${icon('eye')}</button></div></article>`).join('')}</div><div class="panel-foot duplicate-foot"><span>${g.inferred?'Original order is inferred for at least one imported record.':'Original order uses verified database insertion time.'}</span><div><button class="text-btn" data-merge="${idx}">Merge empty metadata</button><button class="text-btn" data-open-both="${idx}">Open all PDFs ${icon('arrow-up-right')}</button></div></div></section>`).join('')||empty('A little more breathing room.','No duplicate candidates match this scan. Try a broader matching preference in Settings.','check-circle-2')}</div>`;
  updateDuplicateToolbar();actionsBind();hydrate();
  $('#show-ignored').onchange=e=>{state.showIgnored=e.target.checked;loadDuplicates().catch(showError);};if($('#scan-everything'))$('#scan-everything').onclick=()=>{state.duplicateIds=null;loadDuplicates().catch(showError);};
  document.querySelectorAll('[data-duplicate-select]').forEach(b=>b.onchange=()=>{const r=state.groups.flatMap(g=>g.records).find(r=>r.id===b.dataset.duplicateSelect);if(b.checked)state.selected.set(r.id,r);else state.selected.delete(r.id);updateDuplicateToolbar();});
  document.querySelectorAll('[data-ignore]').forEach(b=>b.onclick=async()=>{try{const g=state.groups[Number(b.dataset.ignore)];await api('ignore',{groupKey:g.id,restore:g.ignored});await loadDuplicates();toast(g.ignored?'Warning restored.':'Duplicate warning ignored.');}catch(e){showError(e);}});
  document.querySelectorAll('[data-compare-open]').forEach(b=>b.onclick=()=>{const [g,n]=b.dataset.compareOpen.split(':').map(Number),r=state.groups[g].records[n];preview(r.pdf_url,r.title);});
  document.querySelectorAll('[data-open-both]').forEach(b=>b.onclick=()=>{for(const r of state.groups[Number(b.dataset.openBoth)].records)openURL(r.pdf_url);toast('Your browser may ask to allow multiple PDF tabs.');});
  document.querySelectorAll('[data-keep]').forEach(b=>b.onclick=()=>keepDuplicate(...b.dataset.keep.split(':').map(Number)).catch(showError));
  document.querySelectorAll('[data-merge]').forEach(b=>b.onclick=()=>mergeDialog(state.groups[Number(b.dataset.merge)]));
}
function updateDuplicateToolbar(){const el=$('#duplicate-toolbar');if(!el)return;el.innerHTML=`${button('Select recommended later duplicates','select-recommended','copy','secondary')}<span class="muted">${state.selected.size} selected</span>${state.selected.size?`${button('Review & archive','bulk:archive','archive','primary')}${state.role==='super_admin'?button('Review & delete','bulk:delete','trash-2','secondary'):''}<button class="text-btn" id="clear-duplicate-selection">Clear selection</button>`:''}`;actionsBind();hydrate();if($('#clear-duplicate-selection'))$('#clear-duplicate-selection').onclick=()=>{state.selected.clear();loadDuplicates().catch(showError);};}
async function keepDuplicate(groupIndex,recordIndex){const g=state.groups[groupIndex],keep=g.records[recordIndex],others=g.records.filter(r=>r.id!==keep.id);if(!await confirmDialog('Keep this PDF and archive the others?',`Keep: ${keep.title}. Archive ${others.length} other record(s). Shared links retain their saved destination and files are kept.`,'KEEP & ARCHIVE'))return;
  const results=await api('bulk',{table:'study_materials',operation:'archive',items:others.map(r=>({id:r.id,version:r.version})),confirm:'ARCHIVE '+others.length});
  const failures=results.results.filter(r=>!r.ok);if(failures.length)throw Error(failures.map(r=>r.error).join(' '));toast('Selected keeper retained. Other records archived.');await loadDuplicates();signalPublicRefresh();
}
function mergeDialog(g){
  modal('Merge metadata safely',`<p>Choose a keeper. Only its empty description, subject, chapter, class and school date are filled; tags are combined. Existing values, URLs, raw data and files are preserved.</p><form id="merge-form"><label>Keep record<select name="keep">${g.records.map(r=>`<option value="${esc(r.id)}">${esc(r.title)} · ${esc(r.id)}</option>`).join('')}</select></label><label>Fill missing fields from<select name="from">${[...g.records].reverse().map(r=>`<option value="${esc(r.id)}">${esc(r.title)} · ${esc(r.id)}</option>`).join('')}</select></label><p class="form-error"></p><div class="modal-actions"><button class="btn primary">Merge empty fields</button></div></form>`);
  $('#merge-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),keep=g.records.find(r=>r.id===form.get('keep'));try{if(form.get('keep')===form.get('from'))throw Error('Choose two different records.');await api('merge',{keep:keep.id,from:form.get('from'),version:keep.version,confirm:'MERGE'});modalDirty=false;$('#modal').close();toast('Missing metadata merged.');await loadDuplicates();}catch(err){e.target.querySelector('.form-error').textContent=err.message;}};
}
function renderSettings(){const p=state.prefs;
  $('#content').innerHTML=pageHead('MAKE IT YOURS','A workspace that works for you.','Personal defaults, saved securely to your administrator account.')+`<form id="settings-form" class="settings-layout"><section class="panel settings-panel"><div class="panel-head"><div><h2>Content defaults</h2><p>Start each new record one step ahead.</p></div>${icon('files')}</div><div class="settings-fields"><label>Default PDF sort<select name="pdfSort">${[['newest','School date: newest first'],['oldest','School date: oldest first'],['edited','Recently edited'],['inserted','Latest inserted']].map(([v,t])=>`<option value="${v}" ${(p.pdfSort||'newest')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Default announcement sort<select name="announcementSort">${[['newest','Message date: newest first'],['oldest','Message date: oldest first'],['edited','Recently edited'],['inserted','Latest inserted']].map(([v,t])=>`<option value="${v}" ${(p.announcementSort||'newest')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Default subject<input name="defaultSubject" maxlength="120" value="${esc(p.defaultSubject||'')}" placeholder="No default"></label><label>Duplicate matching<select name="duplicateStrictness">${[['exact','Exact URL / checksum only'],['balanced','Balanced · include close metadata matches'],['broad','Broad · include more possible similarities']].map(([v,t])=>`<option value="${v}" ${(p.duplicateStrictness||'balanced')===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="toggle-field"><span><strong>Publish new uploads by default</strong><small>You can change this before every upload.</small></span><input role="switch" type="checkbox" name="defaultPublished" ${p.defaultPublished?'checked':''}></label><div class="setting-info">${icon('shield-check')}Server-enforced upload limit: <strong>20 MB per PDF</strong></div></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Appearance & feedback</h2><p>A quieter, more comfortable workspace.</p></div>${icon('settings')}</div><div class="settings-fields"><label>Visual theme<select name="theme"><option value="dark" ${p.theme!=='light'?'selected':''}>Graphite · Dark</option><option value="light" ${p.theme==='light'?'selected':''}>Ivory · Light</option></select></label><label class="toggle-field"><span><strong>Upload notifications</strong><small>Show success toasts for completed uploads.</small></span><input type="checkbox" role="switch" name="notifications" ${p.notifications!==false?'checked':''}></label><label class="toggle-field"><span><strong>Reduced animations</strong><small>Your device’s reduced-motion setting is always respected.</small></span><input type="checkbox" role="switch" name="reducedMotion" ${p.reducedMotion?'checked':''}></label><div class="setting-info">${icon('shield-check')}Your role: <strong>${state.role==='super_admin'?'Super Admin':'Admin'}</strong>. Role changes are restricted to the database owner.</div></div></section><div class="settings-save"><span class="muted">Preferences never change access controls or database policies.</span><button class="btn primary" type="submit">${icon('check')}Save preferences</button></div></form>`;
  hydrate();$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),preferences=Object.fromEntries(f);for(const k of ['defaultPublished','notifications','reducedMotion'])preferences[k]=f.has(k);const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const r=await api('preferences',{preferences});state.prefs=r.preferences;applyPreferences();toast('Preferences saved.');}catch(err){showError(err);}finally{b.disabled=false;}};
}
function route(){const next=location.hash.slice(1)||'dashboard';if(!nav.some(n=>n[0]===next))return;state.page=next;state.pagination=1;state.search='';state.status='all';state.selected.clear();for(const k of ['subject','source','class_name','chapter','category','from','to'])state[k]='';state.sort=next==='announcements'?(state.prefs.announcementSort||'newest'):(state.prefs.pdfSort||'newest');loadPage().catch(showError);}
async function start(){try{const s=await api('session');state.role=s.role;state.prefs=s.preferences;applyPreferences();shell();route();clearInterval(poll);poll=setInterval(()=>{if(!document.hidden&&!state.busy&&!uploadRunning&&!$('#modal').open&&!['upload','settings'].includes(state.page)&&!$('#search')?.matches(':focus'))loadPage(true).catch(showError);},45000);}catch(e){
  if(e.status===403){state.role=null;$('#app').innerHTML=`<main class="access-denied"><div class="auth-lock">${icon('shield-check')}</div><span class="eyebrow">RESTRICTED WORKSPACE</span><h1>Access denied.</h1><p>Your account is signed in but has no active administrator role.<br>Contact the site owner to request access.</p><button class="btn secondary" id="denied-logout">Sign out</button><a href="/" class="text-link">Return to the website</a></main>`;$('#denied-logout').onclick=async()=>{await logout();authScreen();};hydrate();}
  else if(e.status===401)authScreen();else{authScreen(e.message);}
}}
window.addEventListener('hashchange',()=>{if(state.role)route();});
window.addEventListener('beforeunload',e=>{if(uploadRunning||modalDirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search'))$('#search').focus();else if(state.role)location.hash='library';}});
try{state.queue=JSON.parse(sessionStorage.getItem('8apdf_admin_queue')||'[]').map(j=>({...j,status:'queued'}));}catch{}
try{if(authCallback()){authMode='password';authScreen();}else await start();}catch(e){authScreen(e.message);}
